import "server-only";

import { z } from "zod";
import { db } from "@/lib/db";
import { BillingError } from "./config";
import { dodoClient } from "./dodo";
import { providerSubscriptionSchema } from "./events";
import { reconcileBillingSubscription } from "./lifecycle";
import { ensureBillingBinding } from "./store";
import { withUsageTransaction } from "@/lib/usage-ledger";

export async function cancelBillingSubscription(
  userId: string,
  input: unknown,
) {
  if (!z.object({}).strict().safeParse(input).success)
    throw new BillingError(
      "INVALID_CANCELLATION",
      "Send an empty object.",
      400,
    );
  const reservation = await withUsageTransaction(db, userId, async ({ tx }) => {
    await ensureBillingBinding(tx);
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    const subscription = await tx.billingSubscription.findFirst({
      where: { userId, dodoSubscriptionId: user.dodoSubscriptionId ?? "" },
    });
    if (!subscription || subscription.dodoCustomerId !== user.dodoCustomerId)
      throw new BillingError(
        "NO_SUBSCRIPTION",
        "No current subscription is available.",
        409,
      );
    if (
      subscription.cancelAtPeriodEnd ||
      ["CANCELLED", "EXPIRED", "FAILED"].includes(subscription.status)
    )
      return { subscription, requested: false };
    // Claim before any provider write. Concurrent calls reuse this durable marker.
    if (subscription.cancelRequestedAt)
      return { subscription, requested: false };
    await tx.billingSubscription.updateMany({
      where: { userId, id: subscription.id },
      data: { cancelRequestedAt: new Date() },
    });
    await tx.user.update({
      where: { id: userId },
      data: { billingStateVersion: { increment: 1 } },
    });
    return { subscription, requested: true };
  });
  if (reservation.requested) {
    await dodoClient()
      .subscriptions.update(
        reservation.subscription.dodoSubscriptionId,
        {
          cancel_at_next_billing_date: true,
        },
        { maxRetries: 0 },
      )
      .catch(() => {
        // A timeout is uncertain. Recovery reads provider state before retrying.
      });
  }
  return {
    cancellationPending:
      !reservation.subscription.cancelAtPeriodEnd &&
      !["CANCELLED", "EXPIRED", "FAILED"].includes(
        reservation.subscription.status,
      ),
  };
}

export async function recoverBillingCancellation(
  userId: string,
  subscriptionId: string,
) {
  const stored = await db.billingSubscription.findFirst({
    where: {
      userId,
      dodoSubscriptionId: subscriptionId,
      cancelRequestedAt: { not: null },
    },
  });
  if (!stored) return;
  await withUsageTransaction(db, userId, ({ tx }) => ensureBillingBinding(tx));
  const provider = providerSubscriptionSchema.parse(
    await dodoClient().subscriptions.retrieve(subscriptionId),
  );
  if (
    provider.subscription_id !== subscriptionId ||
    provider.customer.customer_id !== stored.dodoCustomerId ||
    (provider.metadata.mailloopUserId &&
      provider.metadata.mailloopUserId !== userId)
  )
    throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
  if (
    !provider.cancel_at_next_billing_date &&
    !["cancelled", "expired", "failed"].includes(provider.status)
  ) {
    // Allow the first request time to settle before retrying the same idempotent flag.
    if (Date.now() - stored.cancelRequestedAt!.getTime() < 30_000) return;
    await dodoClient().subscriptions.update(
      subscriptionId,
      { cancel_at_next_billing_date: true },
      { maxRetries: 0 },
    );
  }
  await reconcileBillingSubscription(userId, subscriptionId);
}
